import { ListReceiverProps } from "@/core/components/blocks/list-block/list-block";
import structure from "@/core/styling/structure.module.less";
import { AnimatePresence, motion } from "framer-motion";
import EventAggregator from "@/core/helpers/event-aggregator";
import { useEffect, useState } from "react";
import styles from "./base-list-group-renderer.module.less";
import { multipleClassNames } from "@/core/helpers";

export type ListGroup<T> = {
  id: string;
  headline: string;
  paragraph?: string;
  isExpanded: boolean;
  align?: "center" | "start";
  listObjects: Array<T>;
};

export type BaseListGroupRendererProps<T> = ListReceiverProps<ListGroup<T>> & {
  renderItem: (props: T) => JSX.Element;
  isExpandableList: boolean;
  listVariant?: "grid" | "wrap";
  className?: string;
};

/**A component that renders headlines (and potential paragraphs) for group of objects.
 * The groups could for example be product groups or restaurant groups.
 * The rendering of each group is handled through the renderItem props */
const BaseListGroupRenderer = <T,>({
  data,
  renderItem,
  isExpandableList,
  listVariant = "grid",
  className,
}: BaseListGroupRendererProps<T>) => {
  const [isExpanded, _setIsExpanded] = useState<Record<string, boolean>>({});

  useEffect(() => {
    // This makes it so that all lists reset to their initial expanded state once filters change
    _setIsExpanded({});
  }, [data, isExpandableList]);
  const setIsExpanded = ({ id, headline }: ListGroup<T>, expanded: boolean) => {
    _setIsExpanded({ ...isExpanded, [id]: expanded });

    EventAggregator.publish("trackEvent", {
      category: "List",
      action: expanded ? "Opened" : "Closed",
      label: headline,
    });
  };

  return (
    <div
      className={`${structure.blockMaxWidthM} ${structure.blockPadded} ${structure.blockPaddedExceptOnLarge}
    ${className ?? ""}`}
    >
      {data?.map((group) => {
        const { id, headline, paragraph, listObjects, isExpanded: initialExpanded, align = "start" } = group;
        const groupIsExpanded = !isExpandableList || (isExpanded[id] ?? initialExpanded ?? true);

        return (
          <div className={multipleClassNames(styles.innerWrapper, align === "center" && styles.center)} key={id}>
            <h2
              className={`heading-m ${styles.text}`}
              onClick={() => isExpandableList && setIsExpanded(group, !groupIsExpanded)}
            >
              {headline}
            </h2>
            {paragraph && groupIsExpanded && <p className={styles.text}>{paragraph}</p>}
            <motion.div
              key={id}
              className={styles.listWrapper}
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              data-list-variant={listVariant}
              data-list-align={align}
            >
              <AnimatePresence mode="popLayout">
                {groupIsExpanded &&
                  listObjects.map((item, i) => {
                    return (
                      <motion.div
                        key={`${i}-${JSON.stringify(item)}`}
                        initial={{ opacity: 0, scale: 0.5 }}
                        exit={{ opacity: 0 }}
                        whileInView={{ opacity: 1, scale: 1 }}
                        viewport={{ once: true }}
                        transition={{ duration: 0.5 }}
                        className={styles.listItemWrapper}
                      >
                        {renderItem(item)}
                      </motion.div>
                    );
                  })}
              </AnimatePresence>
            </motion.div>
          </div>
        );
      })}
    </div>
  );
};

export default BaseListGroupRenderer;
